{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C12","C15","C07","C29","C03","C10","C23","C04","C42","C20","C127","C108","C113","C128","C239","C218","C221","C240","C206","C211","C244"],
  "contradictory_card_ids": ["C191","C190","C162","C194","C182","C188","C153","C165","C172","C181","C154","C158"],
  "prediction_basis_card_ids": ["C12","C07","C03","C04","C20","C127","C239","C218"],
  "claims": [
    {
      "claim": "Direct L1 and L2 absolute or systemic bioavailability measurements for the fluoroquinolone class are all above the 20% threshold: levofloxacin approaches 100% (C12, C15), ofloxacin approaches 100% (C07, C29), trovafloxacin is 87.6% (C03, C10, C23), moxifloxacin is 86 to 99% (C04, C42), and norfloxacin has a mean of 40% (C20).",
      "card_ids": ["C12","C15","C07","C29","C03","C10","C23","C04","C42","C20"]
    },
    {
      "claim": "L4 absorption records show near-complete oral absorption for the class: levofloxacin is almost completely absorbed (C127), ofloxacin is 85 to 95% absorbed (C108, C113, C128), and ciprofloxacin shows 78% proximal absorption with estimated fraction absorbed above 80% (C98, C120).",
      "card_ids": ["C127","C108","C113","C128","C98","C120"]
    },
    {
      "claim": "L5 efflux evidence shows fluoroquinolones are P-gp, BCRP, and MRP2 substrates (C191, C162, C194, C182, C188), but direct class F values already include this efflux and remain above 20%, so efflux alone does not establish F below 20%.",
      "card_ids": ["C191","C162","C194","C182","C188"]
    },
    {
      "claim": "L6 hepatic clearance evidence shows low-to-moderate intrinsic clearance for fluoroquinolones: an aminopyrrolidine fluoroquinolone structurally similar to the query has HLM CLint of 33.49 µL/min/mg with a 41 minute half-life and enhanced metabolic stability (C239, C218, C221), levofloxacin has the lowest CLint in the class rank order (C240), ciprofloxacin has low hepatic plasma clearance (C206), and moxifloxacin has low hepatocyte CLint (C211, C244).",
      "card_ids": ["C239","C218","C221","C240","C206","C211","C244"]
    },
    {
      "claim": "Trovafloxacin undergoes UGT-mediated acyl-glucuronidation (C197, C201, C207) yet retains 87.6% oral bioavailability (C03), showing that hepatic conjugation does not drive fluoroquinolone F below 20%.",
      "card_ids": ["C197","C201","C207","C03"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C239","C218","C221","C240","C206","C211","C244","C197","C201","C223","C224"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No query-specific hepatic clearance or metabolic stability assay is available; L6 records are for other fluoroquinolones and some non-human systems.",
    "The magnitude of hepatic first-pass loss for the query is unknown, but class-level F values already include first-pass effects and remain above 20%.",
    "No query-specific formulation, dose, or prandial-state data are available.",
    "The query N1 fluorocyclopropyl and C8 chlorine substituents lack direct analog bioavailability records."
  ],
  "decision_summary": "L6 hepatic clearance and metabolic stability evidence is supportive: fluoroquinolones, including an aminopyrrolidine analog similar to the query, show low-to-moderate intrinsic clearance and metabolic stability (C239, C218, C221, C240, C206), and UGT glucuronidation of trovafloxacin does not prevent its 87.6% F (C197, C201, C03). This resolves the mixed metabolism prior in favor of high F. The prediction remains high with moderate confidence because no query-specific F or clearance measurement exists."
}

